//! 🪢️ A pending default leaf keeps its actual borrowed parent action before close.
use semio_framework_value_control_contract::*;
use semio_framework_value_native_decoding::OriginalReceivingPrimary;
use semio_framework_value_native_default::{NativeDefaultCursor,NativeDefaultValue,NativeDefaultValueCursor};
use semio_framework_value_retirement::retirement::RetireOwned;
use semio_framework_value_testing_admission::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
struct Probe;
impl RetireOwned for Probe{type RetirementCursor=<u8 as RetireOwned>::RetirementCursor;fn retirement_seed(self)->Self::RetirementCursor{0u8.retirement_seed()}fn controlled_retirement_supported()->bool{true}}
impl NativeDefaultValue for Probe{fn default_demand()->RetirementDemand{RetirementDemand::default()}fn default_work_demand()->Result<u64,ValueError>{Ok(0)}fn admit_default<'r>(_:&mut Option<Self>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{Ok(reply.pending())}fn recover_default<'r>(_:&mut Option<Self>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}}
struct Driver<'a>{cursor:&'a mut NativeDefaultValueCursor<Probe>,receive:usize,recover:usize}
impl OriginalEffectProducer for Driver<'_>{type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'a,'b>=()where 'b:'a;fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,_:&mut (),effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.receive+=1;self.cursor.advance_local(4096,effect,reply)}fn recover<'r,'a,'b>(&mut self,_:&mut (),effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.recover+=1;self.cursor.recover_advance_local(4096,effect,reply)}}
fn clear<T>(bank:&mut EffectBank,slot:&mut Option<T>){let n=std::mem::size_of::<Option<T>>();let grant=bank.loan(1,n);let ((poll,_),heap)=observe(||bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());drop(slot.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:n,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("cleanup pending")};assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap(),grant,heap)}
#[test]fn pending_leaf_blocks_close_until_the_original_reply_is_recorded(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️work/🥡️placement/pending-leaf.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:128,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut bank=EffectBank::new(Wallet::new(stock,256));let mut cursor=NativeDefaultValueCursor::<Probe>::new();let mut authority=Some(OriginalEffectAuthority::new(Driver{cursor:&mut cursor,receive:0,recover:0}));let mut action=None;let grant=bank.loan(1,4096);let ((first,_),_)=observe(||bank.run(grant,16,|effect|{let ready=authority.as_mut().unwrap().drive(&mut (),effect,&mut action).unwrap();assert!(!ready);RetainedWorkPoll::<(),ValueError>::Pending{work:effect.performed_work()}}));assert!(matches!(first,RetainedWorkPoll::Pending{..}));let observed=authority.as_ref().unwrap().inspect(|driver|(driver.cursor.advance_pending(),driver.cursor.begin_close_demand().is_err(),driver.cursor.output_ready(),driver.cursor.terminal_is_empty()));let ((second,_),heap)=observe(||bank.run(grant,16,|effect|{let ready=authority.as_mut().unwrap().drive(&mut (),effect,&mut action).unwrap();assert!(ready);RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_work()})}));let RetainedWorkPoll::Complete(done)=second else{panic!("recovery pending")};done.result.unwrap();let progress=authority.as_ref().unwrap().inspect(|_|action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap().progress());let _=bank.take_admitted();bank.post(progress,grant,heap);let counts=authority.as_ref().unwrap().inspect(|driver|(driver.receive,driver.recover));let mut output=None;let d=OriginalEffectAuthority::<Driver<'_>>::transfer_reply_demand().unwrap();let grant=bank.loan(1,d.copy_bytes);let ((poll,_),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(authority.as_mut().unwrap().transfer_reply_into(&(),&mut action,&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("reply transfer pending")};assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap().unwrap(),grant,heap);clear(&mut bank,&mut output);let d=OriginalEffectAuthority::<Driver<'_>>::producer_transfer_demand().unwrap();let grant=bank.loan(1,d.copy_bytes);let mut returned=None;let ((poll,_),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&(),&mut returned,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("producer transfer pending")};assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap().unwrap(),grant,heap);clear(&mut bank,&mut returned);drop(returned);drop(authority);assert!(cursor.terminal_is_empty());drop(cursor);assert!(bank.into_wallet().is_ok());assert_eq!(observed,(law["pendingBlocksClose"].as_bool().unwrap(),law["pendingBlocksClose"].as_bool().unwrap(),law["outputBeforeReply"].as_bool().unwrap(),law["emptyBeforeReply"].as_bool().unwrap()));assert_eq!(counts,(law["receiveCalls"].as_u64().unwrap()as usize,law["recoverCalls"].as_u64().unwrap()as usize));}
